import React, { useState, useEffect } from 'react';

function Analytics() {
  const [data, setData]       = useState(null);
  const [loading, setLoading] = useState(true);
  const [filter, setFilter]   = useState('ALL');

  useEffect(() => {
    fetch('http://localhost:5000/api/analytics')
      .then(r => r.json())
      .then(d => { setData(d); setLoading(false); })
      .catch(() => setLoading(false));
  }, []);

  if (loading) return <p style={{ padding: 20 }}>Loading analytics...</p>;
  if (!data)   return <p style={{ padding: 20, color: 'red' }}>Could not connect. Start the backend server.</p>;

  const maxDefects = Math.max(...data.stageData.map(s => s.defects), 1);

  // UAV list from backend — filter by status
  // status values from backend: 'Pass', 'Fail', 'In Progress'
  const allUAVs = data.uavs || [];
  const filteredUAVs = filter === 'ALL'
    ? allUAVs
    : allUAVs.filter(u => u.status === filter);

  const statusColor = s =>
    s === 'Pass' ? '#16a34a' : s === 'Fail' ? '#dc2626' : '#d97706';

  const kpis = [
    { label: 'Total',       value: data.total,           color: '#2563eb', filter: 'ALL'         },
    { label: 'Passed',      value: data.passed,           color: '#16a34a', filter: 'Pass'        },
    { label: 'Failed',      value: data.failed,           color: '#dc2626', filter: 'Fail'        },
    { label: 'In Progress', value: data.inProgress,       color: '#d97706', filter: 'In Progress' },
    { label: 'Pass Rate',   value: data.passRate + '%',   color: '#7c3aed', filter: 'ALL'         },
  ];

  return (
    <div style={{ fontFamily: 'Segoe UI, sans-serif', padding: '20px', maxWidth: '1100px', margin: '0 auto' }}>
      <h2 style={{ marginBottom: '16px' }}>Analytics</h2>

      <div style={{ display: 'flex', gap: '12px', flexWrap: 'wrap', marginBottom: '20px' }}>
        {kpis.map(k => {
          const active = filter === k.filter && k.label !== 'Pass Rate';
          return (
            <div
              key={k.label}
              onClick={() => setFilter(k.filter)}
              style={{
                border: `2px solid ${k.color}`,
                borderRadius: '8px',
                padding: '12px 20px',
                textAlign: 'center',
                cursor: 'pointer',
                minWidth: '100px',
                background: active ? k.color + '18' : 'white',
                boxShadow: active ? `0 0 0 3px ${k.color}55` : 'none',
                transition: 'all 0.15s',
              }}
            >
              <div style={{ fontSize: '26px', fontWeight: 700, color: k.color }}>{k.value}</div>
              <div style={{ fontSize: '12px', color: '#555', marginTop: 2 }}>{k.label}</div>
            </div>
          );
        })}
      </div>

      {data.total === 0 ? (
        <p>No data yet. Add UAVs first.</p>
      ) : (
        <>
          <div style={card}>
            <h3 style={sectionTitle}>Defects Per Stage</h3>
            {data.stageData.map(s => (
              <div key={s.name} style={{ display: 'flex', alignItems: 'center', gap: '10px', marginBottom: '10px' }}>
                <span style={{ width: '200px', fontSize: '13px' }}>{s.name}</span>
                <div style={{ flex: 1, background: '#eee', height: '22px', borderRadius: '4px', overflow: 'hidden' }}>
                  <div style={{
                    width: `${(s.defects / maxDefects) * 100}%`,
                    minWidth: s.defects > 0 ? '30px' : '0',
                    background: s.defects > 3 ? '#dc2626' : s.defects > 0 ? '#f59e0b' : '#eee',
                    height: '22px',
                    borderRadius: '4px',
                    display: 'flex',
                    alignItems: 'center',
                    paddingLeft: '8px',
                    color: 'white',
                    fontSize: '13px',
                    fontWeight: 600,
                  }}>
                    {s.defects > 0 ? s.defects : ''}
                  </div>
                </div>
                <span style={{ fontSize: '12px', color: '#666', whiteSpace: 'nowrap' }}>
                  D:{s.defects} R:{s.rework} F:{s.failed}
                </span>
              </div>
            ))}
          </div>

          <div style={card}>
            <h3 style={sectionTitle}>Stage Health</h3>
            <table style={tableStyle}>
              <thead>
                <tr style={{ background: '#1e293b', color: 'white' }}>
                  {['Stage', 'Defects', 'Rework', 'Failures', 'Health'].map(h => (
                    <th key={h} style={th}>{h}</th>
                  ))}
                </tr>
              </thead>
              <tbody>
                {data.stageData.map((s, i) => {
                  const health = s.defects === 0 ? 'Good' : s.defects <= 2 ? 'Monitor' : 'Critical';
                  const hColor = s.defects === 0 ? '#16a34a' : s.defects <= 2 ? '#d97706' : '#dc2626';
                  return (
                    <tr key={s.name} style={{ background: i % 2 === 0 ? '#f8fafc' : 'white' }}>
                      <td style={td}>{s.name}</td>
                      <td style={{ ...td, color: s.defects > 0 ? '#dc2626' : '#16a34a', fontWeight: 600 }}>{s.defects}</td>
                      <td style={{ ...td, color: s.rework  > 0 ? '#d97706' : '#16a34a' }}>{s.rework}</td>
                      <td style={{ ...td, color: s.failed  > 0 ? '#dc2626' : '#16a34a' }}>{s.failed}</td>
                      <td style={{ ...td, color: hColor, fontWeight: 700 }}>{health}</td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>

          {data.techStats?.length > 0 && (
            <div style={card}>
              <h3 style={sectionTitle}>Technician Performance</h3>
              <table style={tableStyle}>
                <thead>
                  <tr style={{ background: '#1e293b', color: 'white' }}>
                    {['Technician', 'Total', 'Passed', 'Defects', 'Pass Rate'].map(h => (
                      <th key={h} style={th}>{h}</th>
                    ))}
                  </tr>
                </thead>
                <tbody>
                  {data.techStats.map((t, i) => {
                    const rate   = t.total > 0 ? Math.round((t.passed / t.total) * 100) : 0;
                    const rColor = rate >= 80 ? '#16a34a' : rate >= 50 ? '#d97706' : '#dc2626';
                    return (
                      <tr key={t.techId} style={{ background: i % 2 === 0 ? '#f8fafc' : 'white' }}>
                        <td style={{ ...td, fontWeight: 600 }}>{t.techId}</td>
                        <td style={td}>{t.total}</td>
                        <td style={{ ...td, color: '#16a34a' }}>{t.passed}</td>
                        <td style={{ ...td, color: t.defects > 0 ? '#dc2626' : '#16a34a' }}>{t.defects}</td>
                        <td style={{ ...td, color: rColor, fontWeight: 700 }}>{rate}%</td>
                      </tr>
                    );
                  })}
                </tbody>
              </table>
            </div>
          )}

          <div style={card}>
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '12px' }}>
              <h3 style={{ ...sectionTitle, marginBottom: 0 }}>
                UAV List —&nbsp;
                <span style={{ color: filter === 'ALL' ? '#2563eb' : statusColor(filter) }}>
                  {filter}
                </span>
                <span style={{
                  marginLeft: '10px',
                  background: '#e2e8f0',
                  borderRadius: '12px',
                  padding: '2px 10px',
                  fontSize: '13px',
                  fontWeight: 600,
                  color: '#334155',
                }}>
                  {filteredUAVs.length}
                </span>
              </h3>
              {filter !== 'ALL' && (
                <button
                  onClick={() => setFilter('ALL')}
                  style={{
                    border: '1px solid #94a3b8',
                    background: 'white',
                    borderRadius: '6px',
                    padding: '4px 12px',
                    cursor: 'pointer',
                    fontSize: '12px',
                    color: '#475569',
                  }}
                >
                  Clear Filter ✕
                </button>
              )}
            </div>

            {filteredUAVs.length === 0 ? (
              <p style={{ color: '#94a3b8', fontSize: '14px', margin: 0 }}>
                No UAVs with status "{filter}".
              </p>
            ) : (
              <table style={tableStyle}>
                <thead>
                  <tr style={{ background: '#1e293b', color: 'white' }}>
                    {['#', 'UAV ID', 'Technician', 'Date', 'Status'].map(h => (
                      <th key={h} style={th}>{h}</th>
                    ))}
                  </tr>
                </thead>
                <tbody>
                  {filteredUAVs.map((u, i) => (
                    <tr key={u.id} style={{ background: i % 2 === 0 ? '#f8fafc' : 'white' }}>
                      <td style={{ ...td, color: '#94a3b8' }}>{i + 1}</td>
                      <td style={{ ...td, fontWeight: 700 }}>{u.id}</td>
                      <td style={td}>{u.techId}</td>
                      <td style={{ ...td, color: '#64748b' }}>{u.date}</td>
                      <td style={td}>
                        <span style={{
                          background:   statusColor(u.status) + '18',
                          color:        statusColor(u.status),
                          border:       `1px solid ${statusColor(u.status)}`,
                          borderRadius: '12px',
                          padding:      '2px 12px',
                          fontWeight:   700,
                          fontSize:     '12px',
                        }}>
                          {u.status}
                        </span>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            )}
          </div>
        </>
      )}
    </div>
  );
}

const card = {
  border: '1px solid #e2e8f0',
  borderRadius: '8px',
  padding: '16px',
  marginBottom: '16px',
  background: 'white',
  boxShadow: '0 1px 3px rgba(0,0,0,0.06)',
};

const sectionTitle = {
  margin: '0 0 14px 0',
  fontSize: '16px',
  fontWeight: 700,
  color: '#1e293b',
};

const tableStyle = {
  width: '100%',
  borderCollapse: 'collapse',
  fontSize: '13px',
};

const th = {
  padding: '10px 12px',
  textAlign: 'left',
  fontWeight: 600,
  fontSize: '13px',
};

const td = {
  padding: '10px 12px',
  borderBottom: '1px solid #f1f5f9',
};

export default Analytics;
